{
  "name": "Dossiê do Date - Anna Beatriz",
  "description": "Um quiz interativo e estético para descobrir preferências de encontro em Belo Horizonte."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Option {
  id: string;
  text: string;
  emoji: string;
}

export interface Question {
  id: number;
  question: string;
  options: Option[];
}

export type QuizState = {
  step: number;
  answers: string[]; // Stores the text of the selected answers
  note: string;
};

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, Send, Sparkles, MapPin, Utensils, Music, ChevronRight } from 'lucide-react';
import { Question } from './types';

// --- Configuration Data ---

const QUESTIONS: Question[] = [
  {
    id: 1,
    question: "Se a sua energia hoje fosse um local de BH, qual seria?",
    options: [
      { id: 'a', text: "Modo Capivara Chill (Pampulha, grama e água de coco)", emoji: "🌿" },
      { id: 'b', text: "Vibe Madame em Lourdes (Ar condicionado e taça de vinho)", emoji: "🍷" },
      { id: 'c', text: "Dora Aventureira (Trilha, Cachoeira ou Mirante)", emoji: "🧗‍♀️" },
      { id: 'd', text: "Caos Cultural do Centro (Maletta, Sapucaí ou Mercado Novo)", emoji: "🍻" },
    ]
  },
  {
    id: 2,
    question: "O estômago roncou. Qual a estratégia nutricional?",
    options: [
      { id: 'a', text: "Café da tarde de vó (Broa, pão de queijo e cafezinho)", emoji: "☕" },
      { id: 'b', text: "Jantar de adulto funcional (Massas, Risotos ou Gastronomia)", emoji: "🍝" },
      { id: 'c', text: "Baixa Gastronomia (Torresmo, Fígado com Jiló e Cerveja)", emoji: "🥓" },
      { id: 'd', text: "Street Food (Hambúrguer ou Pizza pra comer com a mão)", emoji: "🍕" },
    ]
  },
  {
    id: 3,
    question: "Para o entretenimento, qual a pedida?",
    options: [
      { id: 'a', text: "Assistir algo quieto (Teatro ou Cinema)", emoji: "🎭" },
      { id: 'b', text: "Fofocar horrores (Barzinho com mesa na calçada)", emoji: "🗣️" },
      { id: 'c', text: "Ouvir música alta (Balada ou Bar com DJ)", emoji: "🪩" },
      { id: 'd', text: "Só andar e julgar casas bonitas (Passeio na Praça da Liberdade)", emoji: "💅" },
    ]
  }
];

// --- Components ---

const ProgressBar = ({ current, total }: { current: number; total: number }) => {
  const progress = Math.min((current / total) * 100, 100);
  return (
    <div className="w-full h-1.5 bg-gray-100 rounded-full mb-6 overflow-hidden">
      <motion.div 
        className="h-full bg-gradient-to-r from-pink-400 to-purple-400"
        initial={{ width: 0 }}
        animate={{ width: `${progress}%` }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      />
    </div>
  );
};

export default function App() {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<string[]>([]);
  const [note, setNote] = useState("");

  const handleOptionSelect = (optionText: string) => {
    setAnswers((prev) => [...prev, optionText]);
    setTimeout(() => {
      setStep((prev) => prev + 1);
    }, 250); // Slight delay for ripple/click effect
  };

  const handleWhatsAppRedirect = () => {
    // ⚠️ COLOQUE SEU NÚMERO AQUI (formato internacional sem +: 5531999999999)
    const PHONE_NUMBER = "5531000000000"; 

    const message = `Olá! Segue o dossiê da Anna Beatriz para aprovação:

✨ *Vibe:* ${answers[0]}
🍽️ *Fome:* ${answers[1]}
💃 *Lazer:* ${answers[2]}

📝 *Obs:* ${note || "Nenhuma observação extra."}`;

    const url = `https://api.whatsapp.com/send?phone=${PHONE_NUMBER}&text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  // Determine current icon based on step
  const getHeaderIcon = () => {
    if (step === 0) return <MapPin className="w-6 h-6 text-pink-500" />;
    if (step === 1) return <Utensils className="w-6 h-6 text-purple-500" />;
    if (step === 2) return <Music className="w-6 h-6 text-indigo-500" />;
    return <Sparkles className="w-6 h-6 text-amber-500" />;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-rose-100 via-purple-100 to-teal-100 flex items-center justify-center p-4 font-sans text-slate-700 overflow-hidden">

      {/* Decorative Background Elements */}
      <div className="absolute top-[-10%] right-[-5%] w-64 h-64 bg-purple-200 rounded-full mix-blend-multiply filter blur-3xl opacity-70 animate-pulse"></div>
      <div className="absolute bottom-[-10%] left-[-10%] w-64 h-64 bg-rose-200 rounded-full mix-blend-multiply filter blur-3xl opacity-70 animate-pulse" style={{ animationDelay: '2s' }}></div>

      <motion.div 
        className="relative w-full max-w-md bg-white/80 backdrop-blur-xl shadow-2xl rounded-3xl overflow-hidden border border-white/50"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="p-6 md:p-8">

          {/* Header */}
          <header className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <div className="p-2 bg-white rounded-xl shadow-sm">
                {getHeaderIcon()}
              </div>
              <div>
                <h1 className="text-sm font-semibold uppercase tracking-wider text-gray-400">Dossiê do Date</h1>
                <h2 className="text-lg font-bold text-gray-800 leading-tight">Anna Beatriz</h2>
              </div>
            </div>
            <Heart className="w-5 h-5 text-rose-400 fill-rose-400 animate-pulse" />
          </header>

          <ProgressBar current={step + 1} total={4} />

          {/* Content Swapper */}
          <AnimatePresence mode="wait">
            {step < 3 ? (
              <motion.div
                key={`question-${step}`}
                initial={{ x: 50, opacity: 0 }}
                animate={{ x: 0, opacity: 1 }}
                exit={{ x: -50, opacity: 0 }}
                transition={{ duration: 0.4, ease: "easeOut" }}
              >
                <h3 className="text-xl font-bold mb-6 text-gray-800 leading-snug">
                  {QUESTIONS[step].question}
                </h3>

                <div className="space-y-3">
                  {QUESTIONS[step].options.map((option, index) => (
                    <motion.button
                      key={option.id}
                      onClick={() => handleOptionSelect(option.text)}
                      className="w-full text-left p-4 rounded-xl border border-transparent bg-white shadow-sm hover:shadow-md hover:border-purple-200 hover:bg-purple-50 transition-all duration-300 group flex items-center justify-between"
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: index * 0.1 }}
                      whileTap={{ scale: 0.98 }}
                    >
                      <span className="flex items-center gap-3">
                        <span className="text-2xl filter grayscale group-hover:grayscale-0 transition-all">{option.emoji}</span>
                        <span className="text-sm md:text-base font-medium text-gray-600 group-hover:text-gray-900">{option.text}</span>
                      </span>
                      <ChevronRight className="w-4 h-4 text-gray-300 group-hover:text-purple-400 opacity-0 group-hover:opacity-100 transition-all transform group-hover:translate-x-1" />
                    </motion.button>
                  ))}
                </div>
              </motion.div>
            ) : (
              <motion.div
                key="final-step"
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                transition={{ duration: 0.5 }}
                className="flex flex-col h-full"
              >
                <div className="text-center mb-6">
                  <div className="inline-block p-3 bg-green-100 rounded-full mb-4">
                    <Sparkles className="w-8 h-8 text-green-600" />
                  </div>
                  <h3 className="text-xl font-bold text-gray-800">Quase lá!</h3>
                  <p className="text-gray-500 text-sm mt-1">Só falta aquele detalhe final pra ser perfeito.</p>
                </div>

                <div className="mb-6">
                  <label className="block text-sm font-semibold text-gray-700 mb-2 ml-1">
                    Considerações Finais, Alergias ou Avisos Importantes:
                  </label>
                  <textarea
                    className="w-full p-4 rounded-2xl bg-gray-50 border-2 border-gray-100 focus:border-purple-300 focus:ring-0 focus:outline-none transition-colors text-gray-700 resize-none h-32 text-sm"
                    placeholder="Ex: Odeio coentro, tenho medo de altura, ou 'apenas me surpreenda'..."
                    value={note}
                    onChange={(e) => setNote(e.target.value)}
                  />
                </div>

                <motion.button
                  onClick={handleWhatsAppRedirect}
                  className="w-full py-4 bg-gray-900 text-white rounded-xl font-semibold shadow-lg shadow-gray-300 flex items-center justify-center gap-2 hover:bg-black transition-colors"
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.95 }}
                >
                  <span>Gerar Relatório Oficial</span>
                  <Send className="w-4 h-4" />
                </motion.button>

                <p className="text-xs text-center text-gray-400 mt-4">
                  Ao clicar, você será redirecionada para o WhatsApp.
                </p>
              </motion.div>
            )}
          </AnimatePresence>

        </div>
      </motion.div>
    </div>
  );
}

